  "check_code": "import hashlib\nimport json\nimport sqlite3\nfrom pathlib import Path\nRISK_ID = 'RSK-EPGGL-2025Q3-CUR'\nEXPECTED_ACTIONS = ['ACT-EPGGL-DISC-2025-017','ACT-EPGGL-COST-2025-021','ACT-EPGGL-PI-2025-009']\nHISTORICAL_SHA256 = 'f6c7d3b04df10172e5132c052530d1474689f453cd0f118a21fb817cec4577d0'\ndef _db(ws): return Path(ws).parent / 'system' / 'servicenow_irm' / 'state.db'\ndef _row(ws):\n with sqlite3.connect(_db(ws)) as con:\n  con.row_factory = sqlite3.Row\n  return con.execute('SELECT * FROM risk_matters WHERE risk_matter_id = ?', (RISK_ID,)).fetchone()\ndef _has_exposure(c):\n for section_name in ('gross_exposure','forward_exposure','exposure'):\n  s = c.get(section_name) or {}\n  for k in ('quantified_gross_exposure_usd_cents','gross_exposure_usd_cents'):\n   if s.get(k) is not None and int(s[k]) == 384261573: return True\n  for k in ('amount_usd','gross_exposure_usd','quantified_gross_exposure_usd'):\n   if s.get(k) is not None and round(float(s[k])*100) == 384261573: return True\n return False\ndef check_current_rating_and_drivers(ws):\n try:\n  row = _row(ws)\n  if row is None: return {'score':0,'detail':'current assessment not found'}\n  c = json.loads(row['contributing_conditions_json']); h = json.loads(row['review_history_json'])\n  checks = {'is_current':row['is_current']==1,'rating':row['overall_risk_rating']=='High','end_date':row['operational_significance_end_date']=='2027-11-01','variance_bps':row['q3_outside_counsel_variance_bps']==2336,'overdue':c.get('discovery',{}).get('overdue_milestones')==2,'exposure':_has_exposure(c),'effective_date':any(str(e.get('idempotency_key','')).strip() and e.get('effective_date')=='2025-09-30' for e in h)}\n  return {'score':1,'detail':'current assessment is High with all four required drivers'} if all(checks.values()) else {'score':0,'detail':'driver checks failed: '+', '.join(k for k,v in checks.items() if not v)}\n except Exception as exc: return {'score':0,'detail':f'database check failed: {exc}'}\ndef check_controls_and_links(ws):\n try:\n  row = _row(ws); actions = json.loads(row['linked_actions_json']); ok = row['reviewer_id']=='USR-DEPUTY-GC-006' and row['approval_evidence']=='IRM-APR-2025Q3-EPGGL-0041' and actions==EXPECTED_ACTIONS\n  return {'score':1 if ok else 0,'detail':'reviewer, approval evidence, and exact three action links preserved' if ok else f'controls or links differ: reviewer={row[\"reviewer_id\"]}, approval={row[\"approval_evidence\"]}, actions={actions}'}\n except Exception as exc: return {'score':0,'detail':f'control check failed: {exc}'}\ndef check_reaffirmation_history(ws):\n try:\n  row = _row(ws); history = json.loads(row['review_history_json']); matches = [e for e in history if str(e.get('idempotency_key','')).strip() and e.get('effective_date')=='2025-09-30']\n  ok = len(matches)==1 and matches[0].get('result')=='Approved High' and matches[0].get('linked_remediation_action_ids')==EXPECTED_ACTIONS\n  return {'score':1 if ok else 0,'detail':'exactly one idempotent Approved High event persisted' if ok else f'matching history events={len(matches)}'}\n except Exception as exc: return {'score':0,'detail':f'history check failed: {exc}'}\ndef check_historical_rows_unchanged(ws):\n try:\n  with sqlite3.connect(_db(ws)) as con:\n   con.row_factory = sqlite3.Row; rows = [dict(r) for r in con.execute('SELECT * FROM risk_matters WHERE is_current = 0 ORDER BY risk_matter_id')]\n  digest = hashlib.sha256(json.dumps(rows, sort_keys=True, separators=(',',':')).encode()).hexdigest(); ok = digest == HISTORICAL_SHA256\n  return {'score':1 if ok else 0,'detail':'historical assessments unchanged' if ok else f'historical digest changed to {digest}'}\n except Exception as exc: return {'score':0,'detail':f'historical-row check failed: {exc}'}"
